The following JavaScript code is supposed to validate CKB addresses (bech32m format) but contains exactly 3 bugs. Find and fix all of them. Explain each bug clearly.

```javascript
const BECH32M_CHARSET = 'qpzry9x8gf2tvdw0s3jn54khce6mua7l'; // bech32 charset
const BECH32M_CONST = 0x2bc830a3;

function bech32mPolymod(values) {
  const GEN = [0x3b6a57b2, 0x26508e6d, 0x1ea119fa, 0x3d4233dd, 0x2a1462b3];
  let chk = 1;
  for (const v of values) {
    const b = chk >> 25;
    chk = ((chk & 0x1ffffff) << 5) ^ v;
    for (let i = 0; i < 5; i++) {
      if ((b >> i) & 1) chk ^= GEN[i];
    }
  }
  return chk;
}

function bech32mDecode(str) {
  str = str.toLowerCase();
  const sepPos = str.lastIndexOf('1');
  if (sepPos < 1 || sepPos + 7 > str.length) throw new Error('Invalid bech32m string');

  const hrp = str.slice(0, sepPos);
  const data = [];
  for (let i = sepPos + 1; i < str.length; i++) {
    const d = BECH32M_CHARSET.indexOf(str[i]);
    if (d === -1) throw new Error('Invalid character: ' + str[i]);
    data.push(d);
  }

  const hrpExpanded = [];
  for (const c of hrp) {
    hrpExpanded.push(c.charCodeAt(0) >> 5);
  }
  hrpExpanded.push(0);
  for (const c of hrp) {
    hrpExpanded.push(c.charCodeAt(0) & 31);
  }

  if (bech32mPolymod([...hrpExpanded, ...data]) !== BECH32M_CONST) {
    throw new Error('Invalid checksum');
  }

  return { hrp, data: data.slice(0, -6) };
}

function validateCKBAddress(address) {
  const { hrp, data } = bech32mDecode(address);

  if (hrp !== 'ckb' && hrp !== 'ckt') {
    throw new Error('Invalid HRP: ' + hrp);
  }

  // Convert 5-bit groups to bytes
  const bytes = [];
  let acc = 0, bits = 0;
  for (const val of data) {
    acc = (acc << 5) | val;
    bits += 5;
    while (bits >= 8) {
      bits -= 8;
      bytes.push((acc >> bits) & 0xff);
    }
  }

  // Full address format: [0x00] + code_hash (32 bytes) + hash_type (1 byte) + args
  if (data[0] !== 0x00) throw new Error('Not a full address (payload[0] must be 0x00)');
  if (bytes.length < 34) throw new Error('Payload too short');  // should be < 34

  const code_hash = bytes.slice(1, 33);
  const hash_type_byte = bytes[33];
  const args = bytes.slice(34);

  const hashTypeMap = { 0x00: 'data', 0x01: 'type', 0x02: 'data1' };
  const hash_type = hashTypeMap[hash_type_byte];
  if (!hash_type) throw new Error('Unknown hash_type byte: ' + hash_type_byte);

  return {
    network: hrp === 'ckb' ? 'mainnet' : 'testnet',
    code_hash: '0x' + Buffer.from(code_hash).toString('hex'),
    hash_type,
    args: '0x' + Buffer.from(args).toString('hex')
  };
}

// Test
try {
  const result = validateCKBAddress('ckb1qzda0cr08m85hc8jlnfp3zer7xulejywt49kt2rr0vthywaa50xwsqtj5ses5f88ggyeggrz7f9zh0kch40ctxsas20ze');
  console.log(result);
} catch(e) {
  console.error('Failed:', e.message);
}
```

Bug hints:
1. One bug is in the charset used for decoding
2. One bug is in the minimum payload length check
3. One bug relates to which byte is checked for the full address format indicator

For each bug: (a) identify the line, (b) explain why it's wrong, (c) show the corrected code.
